test("reviewer inspects semantic working and published views with zero mutation surfaces",async()=>{
  const readOnly={can_write:false,can_publish:false,can_unpublish:false,can_archive:false,can_restore:false,can_view_working:true,can_view_published:true};
  const gallery=mediaItem("place-plc-a-b-gallery-a","gallery","approved gallery");
  const working=detail({content:content({name_th:"working authoritative",description_th:"working body",tags:["lake","quiet"],latitude:8.5,longitude:98.7,gallery_media_ids:[gallery.media_id]}),media:{cover:null,gallery:[gallery]},capabilities:readOnly});
  const published=detail({has_active_draft:true,content:content({name_th:"published authoritative",description_th:"published body"}),media:{cover:null,gallery:[]},capabilities:readOnly});
  const h=readOnlyHarness({role:"reviewer",details:[working,published,working]}); await h.c.init();
  assert.deepEqual(h.calls,[["detail",{place_id:ID,view:"working"}]]); assert.equal(h.v.form.hidden,true); assert.equal(h.v.readonly.hidden,false); assert.equal(h.v.readonlySwitch.hidden,false); assert.equal(h.v.save.hidden,true); assert.equal(h.v.publish.hidden,true);
  assert.match(renderedText(h.v.readonlyDetail),/working authoritative/); assert.match(renderedText(h.v.readonlyDetail),/working body/); assert.match(renderedText(h.v.readonlyDetail),/lake/); assert.match(renderedText(h.v.readonlyDetail),/Hero/); assert.match(renderedText(h.v.readonlyDetail),/approved gallery/); assert.equal(descendants(h.v.readonlyDetail).filter((node)=>node.tagName==="IMG").length,1); assert.equal(h.mapInits.length,0); assert.equal(h.mediaInits.length,0);
  await h.v.form.fire("submit"); await h.v.publish.fire("click"); assert.equal(h.calls.length,1); await h.v.readonlyPublished.fire("click"); assert.deepEqual(h.calls[1],["detail",{place_id:ID,view:"published"}]); assert.match(renderedText(h.v.readonlyDetail),/published authoritative/); assert.doesNotMatch(renderedText(h.v.readonlyDetail),/working authoritative/); assert.equal(h.v.readonlyPublished.getAttribute("aria-pressed"),"true");
  await h.v.readonlyWorking.fire("click"); assert.deepEqual(h.calls[2],["detail",{place_id:ID,view:"working"}]); assert.match(renderedText(h.v.readonlyDetail),/working authoritative/); assert.equal(h.calls.some((call)=>["create","save","publish"].includes(call[0])),false);
});
