test("all seven editable field classes compare server-semantic equivalents clean and meaningful changes dirty",async()=>{
  const cases=[
    {label:"scalar",base:{name_th:"Alpha"},equivalent(h){h.v.controls.name_th.value="  Alpha  ";},different(h){h.v.controls.name_th.value="Beta";}},
    {label:"URL",base:{website_url:"https://example.test/place"},equivalent(h){h.v.controls.website_url.value="  https://example.test/place  ";},different(h){h.v.controls.website_url.value="https://example.test/other";}},
    {label:"list",base:{tags:["lake","quiet"]},equivalent(h){h.v.controls.tags.value=" lake, , quiet ";},different(h){h.v.controls.tags.value="quiet,lake";}},
    {label:"numeric",base:{sort_order:1},equivalent(h){h.v.controls.sort_order.value="1e0";},different(h){h.v.controls.sort_order.value="2";}},
    {label:"boolean",base:{is_featured:true},equivalent(h){h.v.controls.is_featured.checked=true;},different(h){h.v.controls.is_featured.checked=false;}},
    {label:"coordinates",base:{latitude:8.9,longitude:98.7},equivalent(h){h.v.controls.latitude.value="08.9000";h.v.controls.longitude.value="098.700";},different(h){h.v.controls.longitude.value="";}},
    {label:"Gallery",base:{gallery_media_ids:["place-plc-a-b-gallery-a","place-plc-a-b-gallery-b"]},equivalent(h){h.setMediaSelected(["place-plc-a-b-gallery-a","place-plc-a-b-gallery-b"]);},different(h){h.setMediaSelected(["place-plc-a-b-gallery-b","place-plc-a-b-gallery-a"]);},event:"click"}
  ];
  for(const entry of cases){const h=readOnlyHarness({role:"editor",details:[detail({content:content(entry.base)})]});await h.c.init();entry.equivalent(h);await (entry.event?h.v.media:h.v.form).fire(entry.event||"input");assert.equal(h.listenerCount("beforeunload"),0,`${entry.label} equivalent`);entry.different(h);await (entry.event?h.v.media:h.v.form).fire(entry.event||"input");assert.equal(h.listenerCount("beforeunload"),1,`${entry.label} difference`);}
});
test("bare Create establishes a clean baseline and tab-only interaction never creates an unsaved warning",async()=>{const h=readOnlyHarness({role:"editor",search:""});await h.c.init();assert.equal(h.listenerCount("beforeunload"),0);await h.v.tabs[1].fire("click");assert.equal(h.listenerCount("beforeunload"),0);h.v.controls.name_en.value="new place";await h.v.form.fire("input");assert.equal(h.listenerCount("beforeunload"),1);});
test("map and Gallery initialization stay clean while coordinate and ordered selection changes become dirty",async()=>{const base=content({latitude:8.2,longitude:98.4,gallery_media_ids:["place-plc-a-b-gallery-a"]});const h=readOnlyHarness({role:"editor",details:[detail({content:base})]});await h.c.init();assert.equal(h.listenerCount("beforeunload"),0);h.v.controls.latitude.value="8.300000";h.v.controls.longitude.value="98.500000";await h.v.map.fire("click");await Promise.resolve();assert.equal(h.listenerCount("beforeunload"),1);h.v.controls.latitude.value="8.2";h.v.controls.longitude.value="98.4";await h.v.form.fire("input");assert.equal(h.listenerCount("beforeunload"),0);h.setMediaSelected(["place-plc-a-b-gallery-b","place-plc-a-b-gallery-a"]);await h.v.media.fire("click");await Promise.resolve();assert.equal(h.listenerCount("beforeunload"),1);});
test("dirty Back navigation uses one bounded same-origin focus-managed dialog and confirm cannot carry an arbitrary href",async()=>{const h=readOnlyHarness({role:"editor",details:[detail()]});await h.c.init();h.v.controls.name_en.value="local";await h.v.form.fire("input");h.v.back.href="https://attacker.invalid/?token=secret";const click=await h.v.back.fire("click");assert.equal(click.defaultPrevented,true);assert.equal(h.v.navigationDialog.open,true);assert.equal(h.document.activeElement,h.v.navigationCancel);assert.deepEqual(h.assigned,[]);await h.v.navigationDialog.fire("cancel");assert.equal(h.v.navigationDialog.open,false);assert.equal(h.document.activeElement,h.v.back);await h.v.back.fire("click");await h.v.navigationConfirm.fire("click");assert.deepEqual(h.assigned,["places.html"]);assert.equal(h.listenerCount("beforeunload"),0);});
test("Save CONFLICT preserves local content and version N through Keep Editing and a second explicit Save",async()=>{const conflict=Object.assign(new Error("RAW stale row"),{code:"CONFLICT"});const latest=detail({working_version:9,entity_version:9,content:content({name_th:"latest authoritative",latitude:9,longitude:99,gallery_media_ids:[]})});const h=readOnlyHarness({role:"editor",details:[detail(),latest],saves:[conflict,conflict]});await h.c.init();h.v.controls.name_th.value="local unsaved";h.v.controls.latitude.value="8.888";h.setMediaSelected(["place-plc-a-b-gallery-local"]);await h.v.form.fire("input");await h.v.form.fire("submit");assert.equal(h.calls.filter((call)=>call[0]==="save").length,1);assert.equal(h.v.conflictDialog.open,true);assert.equal(h.listenerCount("beforeunload"),1);await h.v.conflictKeep.fire("click");assert.equal(h.v.controls.name_th.value,"local unsaved");assert.equal(h.calls.filter((call)=>call[0]==="detail").length,1);await h.v.form.fire("submit");const saves=h.calls.filter((call)=>call[0]==="save");assert.equal(saves.length,2);assert.deepEqual(saves.map((call)=>call[1].expected_version),[4,4]);assert.equal(h.v.controls.latitude.value,"8.888");assert.deepEqual(h.getMediaSelected(),["place-plc-a-b-gallery-local"]);assert.equal(h.listenerCount("beforeunload"),1);await h.v.conflictReload.fire("click");assert.equal(h.calls.filter((call)=>call[0]==="detail").length,2);assert.equal(h.calls.filter((call)=>["save","publish","archive"].includes(call[0])).length,2);assert.equal(h.v.controls.name_th.value,"latest authoritative");assert.equal(h.listenerCount("beforeunload"),0);});
test("failed Save keeps normalized dirty state and restores controls for only an explicit retry",async()=>{const failed=Object.assign(new Error("RAW backend"),{code:"SERVER_ERROR"});const h=readOnlyHarness({role:"editor",details:[detail(),detail()],saves:[failed,write()]});await h.c.init();h.v.controls.description_th.value="retain me";await h.v.form.fire("input");await h.v.form.fire("submit");assert.equal(h.listenerCount("beforeunload"),1);assert.equal(h.v.controls.description_th.value,"retain me");assert.equal(h.calls.filter((call)=>call[0]==="save").length,1);assert.equal(h.v.save.disabled,false);assert.doesNotMatch(h.v.status.textContent,/RAW|backend/);await h.v.form.fire("submit");assert.equal(h.calls.filter((call)=>call[0]==="save").length,2);assert.equal(h.listenerCount("beforeunload"),0);});
test("double Publish stays single-flight across Save Publish and authoritative reload",async()=>{const pending=deferred();const h=readOnlyHarness({role:"editor",details:[detail(),detail({working_version:6,entity_version:6})],saves:[pending.promise]});await h.c.init();const first=h.v.publish.fire("click"),duplicate=h.v.publish.fire("click");assert.equal(h.calls.filter((call)=>call[0]==="save").length,1);assert.equal(h.calls.filter((call)=>call[0]==="publish").length,0);pending.resolve(write({working_version:5,entity_version:5}));await Promise.all([first,duplicate]);assert.equal(h.calls.filter((call)=>call[0]==="save").length,1);assert.equal(h.calls.filter((call)=>call[0]==="publish").length,1);assert.equal(h.calls.filter((call)=>call[0]==="detail").length,2);});
test("Archive displays locked execution B after advisory preview A and never submits A as authority",async()=>{const previewA={routes:[{entity_id:"ROUTE-A",label:"Preview A"}],nearby_places:[],products:[],events:[],gallery:[],trip_templates:[],reviews:[]};const executionB={routes:[],nearby_places:[],products:[{entity_id:"PRODUCT-B",label:"Execution B"}],events:[],gallery:[],trip_templates:[],reviews:[]};const empty={routes:[],nearby_places:[],products:[],events:[],gallery:[],trip_templates:[],reviews:[]};const archived=detail({status:"archived",display_state:"archived",entity_version:6,working_version:6,capabilities:{can_write:true,can_publish:false,can_unpublish:false,can_archive:false,can_restore:true,can_view_working:true,can_view_published:true}});const archiveResult=write({status:"archived",working_version:6,entity_version:6,published_version:3,has_active_draft:true,dependencies:executionB});const h=readOnlyHarness({role:"editor",details:[detail(),archived],dependencies:[{place_id:ID,checked_at:"2026-08-10T00:00:00.000Z",groups:previewA}],archives:[archiveResult]});await h.c.init();const first=h.v.archive.fire("click"),duplicate=h.v.archive.fire("click");await Promise.all([first,duplicate]);assert.deepEqual(h.calls.filter((call)=>call[0]==="inspect"),[["inspect",{place_id:ID}]]);assert.match(renderedText(h.v.archiveDependencies),/Preview A/);await h.v.archiveConfirm.fire("click");assert.deepEqual(h.calls.filter((call)=>call[0]==="archive"),[["archive",{place_id:ID,expected_version:4,confirmed:true}]]);assert.doesNotMatch(JSON.stringify(h.calls.filter((call)=>call[0]==="archive")),/Preview A|ROUTE-A|dependency_count|preview|hash|token/);assert.match(renderedText(h.v.archiveDependencies),/Execution B/);assert.doesNotMatch(renderedText(h.v.archiveDependencies),/Preview A/);assert.equal(h.v.archiveDialog.open,true);assert.equal(h.v.archiveConfirm.hidden,true);assert.equal(h.v.archiveConfirm.disabled,true);assert.equal(h.calls.filter((call)=>call[0]==="archive").length,1);
  const zero=readOnlyHarness({role:"editor",details:[detail(),archived],dependencies:[{place_id:ID,checked_at:"2026-08-10T00:00:00.000Z",groups:previewA}],archives:[write({status:"archived",working_version:6,entity_version:6,published_version:3,has_active_draft:true,dependencies:empty})]});await zero.c.init();await zero.v.archive.fire("click");assert.match(renderedText(zero.v.archiveDependencies),/Preview A/);await zero.v.archiveConfirm.fire("click");assert.doesNotMatch(renderedText(zero.v.archiveDependencies),/Preview A/);assert.equal((renderedText(zero.v.archiveDependencies).match(/ไม่มีรายการอ้างอิง/g)||[]).length,7);assert.equal(zero.v.archiveDialog.open,true);
  const appeared=readOnlyHarness({role:"editor",details:[detail(),archived],dependencies:[{place_id:ID,checked_at:"2026-08-10T00:00:00.000Z",groups:empty}],archives:[archiveResult]});await appeared.c.init();await appeared.v.archive.fire("click");assert.equal((renderedText(appeared.v.archiveDependencies).match(/ไม่มีรายการอ้างอิง/g)||[]).length,7);await appeared.v.archiveConfirm.fire("click");assert.match(renderedText(appeared.v.archiveDependencies),/Execution B/);assert.equal(appeared.v.archiveDialog.open,true);
});
test("Archive failure and conflict never display Archived, retry, or force and always restore controls",async()=>{for(const code of ["SERVER_ERROR","CONFLICT"]){const failure=Object.assign(new Error("RAW archive internals"),{code});const h=readOnlyHarness({role:"editor",details:[detail()],archives:[failure]});await h.c.init();const initialLifecycle=h.v.lifecycle.textContent;await h.v.archive.fire("click");await h.v.archiveConfirm.fire("click");assert.equal(h.calls.filter((call)=>call[0]==="archive").length,1);assert.equal(h.calls.filter((call)=>call[0]==="detail").length,1);assert.equal(h.v.lifecycle.textContent,initialLifecycle);assert.equal(h.v.archive.disabled,false);assert.doesNotMatch(JSON.stringify(h.calls),/force/);assert.doesNotMatch(h.v.status.textContent,/RAW|internals/);if(code==="CONFLICT")assert.equal(h.v.conflictDialog.open,true);}});
test("Unpublish and Restore require confirmation and call exact facades once",async()=>{const unpublished=detail({status:"draft",display_state:"draft",entity_version:6,working_version:6,capabilities:{can_write:true,can_publish:true,can_unpublish:false,can_archive:true,can_restore:false,can_view_working:true,can_view_published:true}});const unpublish=readOnlyHarness({role:"editor",details:[detail(),unpublished]});await unpublish.c.init();await unpublish.v.unpublish.fire("click");assert.equal(unpublish.calls.filter((call)=>call[0]==="unpublish").length,0);await unpublish.v.lifecycleConfirm.fire("click");assert.deepEqual(unpublish.calls.filter((call)=>call[0]==="unpublish"),[["unpublish",{place_id:ID,expected_version:4}]]);const archived=detail({status:"archived",display_state:"archived",has_active_draft:true,capabilities:{can_write:true,can_publish:false,can_unpublish:false,can_archive:false,can_restore:true,can_view_working:true,can_view_published:true}});const restored=detail({status:"draft",display_state:"draft",entity_version:5,working_version:5});const restore=readOnlyHarness({role:"editor",details:[archived,restored]});await restore.c.init();await restore.v.restore.fire("click");assert.equal(restore.calls.filter((call)=>call[0]==="restore").length,0);await restore.v.lifecycleConfirm.fire("click");assert.deepEqual(restore.calls.filter((call)=>call[0]==="restore"),[["restore",{place_id:ID,expected_version:4}]]);});
test("reviewer and viewer stay clean without lifecycle conflict or navigation mutation behavior",async()=>{for(const role of ["reviewer","viewer"]){const capabilities={can_write:false,can_publish:false,can_unpublish:false,can_archive:false,can_restore:false,can_view_working:true,can_view_published:true};const h=readOnlyHarness({role,details:[detail({capabilities})]});await h.c.init();await h.v.form.fire("input");await h.v.archive.fire("click");await h.v.back.fire("click");assert.equal(h.listenerCount("beforeunload"),0);assert.equal(h.calls.some((call)=>["inspect","archive","unpublish","restore"].includes(call[0])),false);assert.equal(h.v.conflictDialog.open,false);}});
test("Archive confirmation and lifecycle actions remain single-flight while one write is pending",async()=>{const archivePending=deferred();const archived=detail({status:"archived",display_state:"archived",entity_version:6,working_version:6,capabilities:{can_write:true,can_publish:false,can_unpublish:false,can_archive:false,can_restore:true,can_view_working:true,can_view_published:true}});const archive=readOnlyHarness({role:"editor",details:[detail(),archived],archives:[archivePending.promise]});await archive.c.init();await archive.v.archive.fire("click");const first=archive.v.archiveConfirm.fire("click"),duplicate=archive.v.archiveConfirm.fire("click");assert.equal(archive.calls.filter((call)=>call[0]==="archive").length,1);assert.equal(archive.calls.filter((call)=>call[0]==="inspect").length,1);archivePending.resolve(write({status:"archived",working_version:6,entity_version:6,published_version:3,has_active_draft:true,dependencies:{routes:[],nearby_places:[],products:[],events:[],gallery:[],trip_templates:[],reviews:[]}}));await Promise.all([first,duplicate]);assert.equal(archive.calls.filter((call)=>call[0]==="archive").length,1);
  const lifecyclePending=deferred();const lifecycle=readOnlyHarness({role:"editor",details:[detail(),detail({status:"draft",display_state:"draft",entity_version:6,working_version:6})],unpublishes:[lifecyclePending.promise]});await lifecycle.c.init();await lifecycle.v.unpublish.fire("click");const pending=lifecycle.v.lifecycleConfirm.fire("click");await lifecycle.v.archive.fire("click");await lifecycle.v.restore.fire("click");assert.equal(lifecycle.calls.filter((call)=>call[0]==="unpublish").length,1);assert.equal(lifecycle.calls.filter((call)=>call[0]==="inspect").length,0);assert.equal(lifecycle.calls.filter((call)=>call[0]==="restore").length,0);lifecyclePending.resolve(write({status:"draft",working_version:6,entity_version:6,published_version:3,has_active_draft:true}));await pending;
});
test("conflict Archive and lifecycle dialogs focus safely and Escape or cancel restores the trigger",async()=>{const conflict=Object.assign(new Error("stale"),{code:"CONFLICT"});const save=readOnlyHarness({role:"editor",details:[detail()],saves:[conflict]});await save.c.init();await save.v.form.fire("submit");assert.equal(save.document.activeElement,save.v.conflictKeep);const conflictCancel=await save.v.conflictDialog.fire("cancel");assert.equal(conflictCancel.defaultPrevented,true);assert.equal(save.v.conflictDialog.open,false);assert.equal(save.document.activeElement,save.v.save);
  const archive=readOnlyHarness({role:"editor",details:[detail()]});await archive.c.init();await archive.v.archive.fire("click");assert.equal(archive.document.activeElement,archive.v.archiveCancel);const archiveCancel=await archive.v.archiveDialog.fire("cancel");assert.equal(archiveCancel.defaultPrevented,true);assert.equal(archive.v.archiveDialog.open,false);assert.equal(archive.document.activeElement,archive.v.archive);await archive.v.archive.fire("click");await archive.v.archiveCancel.fire("click");assert.equal(archive.document.activeElement,archive.v.archive);
  const lifecycle=readOnlyHarness({role:"editor",details:[detail()]});await lifecycle.c.init();await lifecycle.v.unpublish.fire("click");assert.equal(lifecycle.document.activeElement,lifecycle.v.lifecycleCancel);const lifecycleCancel=await lifecycle.v.lifecycleDialog.fire("cancel");assert.equal(lifecycleCancel.defaultPrevented,true);assert.equal(lifecycle.v.lifecycleDialog.open,false);assert.equal(lifecycle.document.activeElement,lifecycle.v.unpublish);await lifecycle.v.unpublish.fire("click");await lifecycle.v.lifecycleCancel.fire("click");assert.equal(lifecycle.document.activeElement,lifecycle.v.unpublish);
});
test("native dialog containment wraps Tab and Shift Tab between reachable actions",async()=>{const h=readOnlyHarness({role:"editor",details:[detail()]});await h.c.init();await h.v.unpublish.fire("click");assert.equal(h.document.activeElement,h.v.lifecycleCancel);h.document.activeElement=h.v.lifecycleCancel;const reverse=await h.v.lifecycleDialog.fire("keydown",{key:"Tab",shiftKey:true});assert.equal(reverse.defaultPrevented,true);assert.equal(h.document.activeElement,h.v.lifecycleConfirm);h.document.activeElement=h.v.lifecycleConfirm;const forward=await h.v.lifecycleDialog.fire("keydown",{key:"Tab",shiftKey:false});assert.equal(forward.defaultPrevented,true);assert.equal(h.document.activeElement,h.v.lifecycleCancel);});
test("map pointerup marks coordinate edits dirty while media search and pagination remain clean",async()=>{const h=readOnlyHarness({role:"editor",details:[detail({content:content({latitude:8.2,longitude:98.4,gallery_media_ids:["place-plc-a-b-gallery-a"]})})]});await h.c.init();h.v.mediaSearch.value="waterfall";await h.v.mediaSearchForm.fire("submit");await h.v.media.fire("click");await h.v.mediaPrevious.fire("click");await h.v.media.fire("click");await h.v.mediaNext.fire("click");await h.v.media.fire("click");assert.equal(h.listenerCount("beforeunload"),0);h.v.controls.latitude.value="8.3";h.v.controls.longitude.value="98.5";await h.v.map.fire("pointerup");await Promise.resolve();assert.equal(h.listenerCount("beforeunload"),1);});
test("invalid fields expose one associated summary and focus the first invalid control without writing",async()=>{const h=readOnlyHarness({role:"editor",details:[detail()]});await h.c.init();h.v.controls.latitude.valid=false;h.v.controls.longitude.valid=false;await h.v.form.fire("submit");assert.equal(h.calls.filter((call)=>call[0]==="save").length,0);assert.equal(h.v.validationSummary.hidden,false);assert.match(h.v.validationSummary.textContent,/ตรวจสอบ|ไม่ถูกต้อง/);assert.equal(h.v.controls.latitude.getAttribute("aria-invalid"),"true");assert.match(h.v.controls.latitude.getAttribute("aria-describedby"),/admin-place-validation-summary/);assert.equal(h.v.controls.longitude.getAttribute("aria-invalid"),"true");assert.equal(h.document.activeElement,h.v.controls.latitude);await h.v.form.fire("input",{target:h.v.controls.latitude});assert.equal(h.v.validationSummary.hidden,true);assert.equal(h.v.controls.latitude.getAttribute("aria-invalid"),null);});
test("Thai name exposes required semantics only in Create while Edit Draft remains optional",async()=>{const create=readOnlyHarness({role:"editor",search:""});await create.c.init();assert.equal(create.v.controls.name_th.getAttribute("aria-required"),"true");assert.equal(create.v.nameRequired.hidden,false);const edit=readOnlyHarness({role:"editor",details:[detail()]});await edit.c.init();assert.equal(edit.v.controls.name_th.getAttribute("aria-required"),null);assert.equal(edit.v.nameRequired.hidden,true);});
test("Task 16 page provides native accessible dialogs and exact lifecycle controls without force or direct transport",()=>{for(const hook of ["navigation-dialog","conflict-dialog","archive-dialog","lifecycle-dialog"])assert.match(page,new RegExp(`<dialog[^>]*data-admin-place-${hook}`));for(const hook of ["unpublish","archive","restore"])assert.match(page,new RegExp(`data-admin-place-${hook}`));assert.match(page,/aria-labelledby="admin-place-(?:navigation|conflict|archive|lifecycle)-title"/);assert.doesNotMatch(source,/\bfetch\s*\(|innerHTML|force\s*:|dependency_count|preview_hash|preview_token/);});
(async()=>{let bad=0;for(const t of tests){try{await t.fn();console.log(`PASS ${t.name}`);}catch(e){bad++;console.error(`FAIL ${t.name}\n${e.stack||e}`);}}if(bad){process.exitCode=1;}else console.log(`Admin Place editor verification passed: ${tests.length} tests.`);})();
